_DS_CU = '// Ballot-ranking probe (plan/proposal-warp-ballot-and-shifts.md, Staging step 2).\n// Three CUDA downsweeps with the SAME interface and output as Crisp\'s sort_downsweep (v1j):\n//   variant 0  ds_split2      -- a straight port of Crisp\'s two 4-bit splits (the CONTROL: nvcc vs Crisp)\n//   variant 1  ds_rank8<0>    -- one 8-bit ranking pass, peers from 8 warp ballots (portable)\n//   variant 2  ds_rank8<1>    -- the same with __match_any_sync (PTX only)\n//   variant 3  ds_rank8<0,6>  -- ballot at 6 workgroups/SM (probe v2: every arm has __launch_bounds__ min blocks)\n// One 256-thread workgroup per 4096-key tile.  Keys are rotated right by SHIFT so the pass\'s digit is\n// the low byte; the last partial tile is padded with ~0 (digit 255, sorts last, never written).\n#include <cstdint>\n#include <stdexcept>\n#include <string>\n#include <cuda_runtime.h>\n\n__device__ __forceinline__ uint32_t f2k(uint32_t b) { return (b >> 31) ? ~b : (b ^ 0x80000000u); }\n__device__ __forceinline__ uint32_t k2f(uint32_t k) { return (k >> 31) ? (k ^ 0x80000000u) : ~k; }\n__device__ __forceinline__ uint32_t keyof(uint32_t b, uint32_t first, uint32_t kmin) {\n    return first ? f2k(b) - kmin : b;\n}\n\n// Exclusive scan of X over 256 threads (8 warps).  Holds barriers.\n__device__ __forceinline__ uint32_t block_excl_scan(uint32_t x, uint32_t* wsum) {\n    const int lane = threadIdx.x & 31, w = threadIdx.x >> 5;\n    uint32_t s = x;\n#pragma unroll\n    for (int o = 1; o < 32; o <<= 1) { uint32_t u = __shfl_up_sync(~0u, s, o); if (lane >= o) s += u; }\n    if (lane == 31) wsum[w] = s;\n    __syncthreads();\n    if (w == 0) {\n        uint32_t v = lane < 8 ? wsum[lane] : 0u, t = v;\n#pragma unroll\n        for (int o = 1; o < 8; o <<= 1) { uint32_t u = __shfl_up_sync(~0u, t, o); if (lane >= o) t += u; }\n        if (lane < 8) wsum[lane] = t - v;\n    }\n    __syncthreads();\n    uint32_t r = wsum[w] + s - x;\n    __syncthreads();\n    return r;\n}\n\n// ---------------------------------------------------------------- variant 0: two 4-bit splits (port)\n__device__ __forceinline__ uint32_t tw(uint32_t p) { return (p & 15u) * 257u + (p >> 4); }\n__device__ __forceinline__ uint32_t cw(uint32_t c) { return c + (c >> 5); }\n__device__ __forceinline__ uint32_t nibfield(uint64_t lo, uint64_t hi, uint32_t d) {\n    return (uint32_t)(((d < 8u ? lo : hi) >> ((d & 7u) * 8u)) & 255ull);\n}\n\n__device__ void split_nibble(const uint32_t* in, uint32_t* out, uint32_t* cnt, uint32_t* wsum, uint32_t t, int sh) {\n    uint64_t lo = 0, hi = 0;\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t d = (in[j * 257 + t] >> sh) & 15u;\n        uint64_t inc = 1ull << ((d & 7u) * 8u);\n        lo += d < 8u ? inc : 0ull; hi += d < 8u ? 0ull : inc;\n    }\n#pragma unroll\n    for (int dg = 0; dg < 16; dg++) cnt[cw(dg * 256 + t)] = nibfield(lo, hi, dg);\n    __syncthreads();\n    uint32_t mine = 0;\n#pragma unroll\n    for (int j = 0; j < 16; j++) mine += cnt[cw(t * 16 + j)];\n    uint32_t run = block_excl_scan(mine, wsum);\n#pragma unroll\n    for (int j = 0; j < 16; j++) { uint32_t c = cw(t * 16 + j), v = cnt[c]; cnt[c] = run; run += v; }\n    __syncthreads();\n    lo = 0; hi = 0;\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t k = in[j * 257 + t], d = (k >> sh) & 15u;\n        uint64_t inc = 1ull << ((d & 7u) * 8u);\n        uint32_t r = cnt[cw(d * 256 + t)] + nibfield(lo, hi, d);\n        lo += d < 8u ? inc : 0ull; hi += d < 8u ? 0ull : inc;\n        out[tw(r)] = k;\n    }\n    __syncthreads();\n}\n\n__global__ void __launch_bounds__(256, 4) ds_split2(const uint32_t* __restrict__ src, const uint32_t* __restrict__ mm,\n        const uint32_t* __restrict__ prm, const uint32_t* __restrict__ scanned, const uint32_t* __restrict__ totals,\n        uint32_t* __restrict__ dst, uint64_t n) {\n    extern __shared__ uint32_t sm[];\n    uint32_t *ta = sm, *tb = ta + 4112, *cnt = tb + 4112, *gofs = cnt + 4224, *lstart = gofs + 256, *wsum = lstart + 256;\n    const uint32_t t = threadIdx.x;\n    const uint64_t bid = blockIdx.x, base = bid * 4096ull;\n    const uint32_t shift = prm[0], first = prm[1], last = prm[2], kmin = mm[0];\n    const uint32_t valid = (uint32_t)min((unsigned long long)4096, (unsigned long long)(n - base));\n    gofs[t] = block_excl_scan(totals[t], wsum) + scanned[bid * 256 + t];\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t p = j * 256 + t, k = ~0u;\n        if (p < valid) { k = keyof(src[base + p], first, kmin); k = __funnelshift_r(k, k, shift); }\n        ta[tw(p)] = k;\n    }\n    __syncthreads();\n    split_nibble(ta, tb, cnt, wsum, t, 0);\n    split_nibble(tb, ta, cnt, wsum, t, 4);\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t p = j * 256 + t, q = p ? p - 1 : 0;\n        uint32_t dg = ta[tw(p)] & 255u, dq = ta[tw(q)] & 255u;\n        if (p == 0 || dg != dq) lstart[dg] = p;\n    }\n    __syncthreads();\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t p = j * 256 + t;\n        if (p < valid) {\n            uint32_t r = ta[tw(p)], d = r & 255u, k = __funnelshift_l(r, r, shift);\n            dst[(uint64_t)gofs[d] + (p - lstart[d])] = last ? k2f(k + kmin) : k;\n        }\n    }\n}\n\n// ---------------------------------------------------------------- variants 1 / 2: one 8-bit ranking pass\n// Warp w owns tile positions [w*512, (w+1)*512), round-major (p = w*512 + j*32 + lane): a coalesced load,\n// and the (digit, warp) scan order below keeps the sort stable.\ntemplate <int MATCH, int MINB>\n__global__ void __launch_bounds__(256, MINB) ds_rank8(const uint32_t* __restrict__ src, const uint32_t* __restrict__ mm,\n        const uint32_t* __restrict__ prm, const uint32_t* __restrict__ scanned, const uint32_t* __restrict__ totals,\n        uint32_t* __restrict__ dst, uint64_t n) {\n    __shared__ uint32_t wcnt[8 * 256];\n    __shared__ uint32_t tile[4096];\n    __shared__ uint32_t gofs[256], lstart[256], wsum[8];\n    const uint32_t t = threadIdx.x, lane = t & 31u, w = t >> 5;\n    const uint64_t bid = blockIdx.x, base = bid * 4096ull;\n    const uint32_t shift = prm[0], first = prm[1], last = prm[2], kmin = mm[0];\n    const uint32_t valid = (uint32_t)min((unsigned long long)4096, (unsigned long long)(n - base));\n    gofs[t] = block_excl_scan(totals[t], wsum) + scanned[bid * 256 + t];\n    for (uint32_t i = t; i < 8 * 256; i += 256) wcnt[i] = 0;\n    __syncthreads();\n    const uint32_t lt = (1u << lane) - 1u;\n    uint32_t rk[16], rank2[8];                   // ranks < 4096: two per register\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t p = w * 512u + j * 32u + lane;\n        uint32_t k = ~0u;\n        if (p < valid) { k = keyof(src[base + p], first, kmin); k = __funnelshift_r(k, k, shift); }\n        rk[j] = k;\n        uint32_t d = k & 255u, peers;\n        if (MATCH) {\n            peers = __match_any_sync(~0u, d);\n        } else {\n            peers = ~0u;\n#pragma unroll\n            for (int b = 0; b < 8; b++) {\n                uint32_t bit = (d >> b) & 1u, v = __ballot_sync(~0u, bit);\n                peers &= bit ? v : ~v;\n            }\n        }\n        uint32_t below = __popc(peers & lt);\n        uint32_t c = wcnt[w * 256u + d];          // every peer reads the same old count\n        __syncwarp();\n        if (below == 0) wcnt[w * 256u + d] = c + __popc(peers);   // the lowest peer bumps it\n        __syncwarp();\n        if (j & 1) rank2[j >> 1] |= (c + below) << 16; else rank2[j >> 1] = c + below;\n    }\n    __syncthreads();\n    // (digit, warp) order: thread t = digit\n    uint32_t cnt[8], tot = 0;\n#pragma unroll\n    for (int ww = 0; ww < 8; ww++) { cnt[ww] = wcnt[ww * 256 + t]; tot += cnt[ww]; }\n    uint32_t run = block_excl_scan(tot, wsum);\n    lstart[t] = run;\n#pragma unroll\n    for (int ww = 0; ww < 8; ww++) { wcnt[ww * 256 + t] = run; run += cnt[ww]; }\n    __syncthreads();\n#pragma unroll\n    for (int j = 0; j < 16; j++) tile[wcnt[w * 256u + (rk[j] & 255u)] + ((rank2[j >> 1] >> ((j & 1) * 16)) & 0xFFFFu)] = rk[j];\n    __syncthreads();\n#pragma unroll\n    for (int j = 0; j < 16; j++) {\n        uint32_t p = j * 256 + t;\n        if (p < valid) {\n            uint32_t r = tile[p], d = r & 255u, k = __funnelshift_l(r, r, shift);\n            dst[(uint64_t)gofs[d] + (p - lstart[d])] = last ? k2f(k + kmin) : k;\n        }\n    }\n}\n\nstatic void ck(cudaError_t e, const char* what) {\n    if (e != cudaSuccess) throw std::runtime_error(std::string(what) + ": " + cudaGetErrorString(e));\n}\n\nvoid ds_launch(int64_t variant, int64_t src, int64_t mm, int64_t prm, int64_t scanned, int64_t totals,\n               int64_t dst, int64_t n) {\n    const unsigned nb = (unsigned)((n + 4095) / 4096);\n    auto S = (const uint32_t*)src; auto M = (const uint32_t*)mm; auto P = (const uint32_t*)prm;\n    auto SC = (const uint32_t*)scanned; auto T = (const uint32_t*)totals; auto D = (uint32_t*)dst;\n    if (variant == 0) {\n        const size_t smem = (4112 * 2 + 4224 + 256 + 256 + 8) * 4;\n        static bool once = false;\n        if (!once) { ck(cudaFuncSetAttribute(ds_split2, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem), "attr"); once = true; }\n        ds_split2<<<nb, 256, smem>>>(S, M, P, SC, T, D, (uint64_t)n);\n    } else if (variant == 1) {\n        ds_rank8<0, 4><<<nb, 256>>>(S, M, P, SC, T, D, (uint64_t)n);\n    } else if (variant == 2) {\n        ds_rank8<1, 4><<<nb, 256>>>(S, M, P, SC, T, D, (uint64_t)n);\n    } else {\n        ds_rank8<0, 6><<<nb, 256>>>(S, M, P, SC, T, D, (uint64_t)n);\n    }\n    ck(cudaGetLastError(), "ds launch");\n}\n\nstd::string ds_info() {\n    std::string r;\n    cudaFuncAttributes a;\n    const void* fns[4] = {(const void*)ds_split2, (const void*)ds_rank8<0, 4>, (const void*)ds_rank8<1, 4>,\n                          (const void*)ds_rank8<0, 6>};\n    const char* names[4] = {"split2", "ballot", "match", "ballot6"};\n    ck(cudaFuncSetAttribute(ds_split2, cudaFuncAttributeMaxDynamicSharedMemorySize,\n                            (int)((4112 * 2 + 4224 + 256 + 256 + 8) * 4)), "attr");\n    for (int i = 0; i < 4; i++) {\n        ck(cudaFuncGetAttributes(&a, fns[i]), "attrs");\n        int blocks = 0;\n        size_t dyn = i == 0 ? (4112 * 2 + 4224 + 256 + 256 + 8) * 4 : 0;\n        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, fns[i], 256, dyn);\n        r += std::string(names[i]) + ": regs=" + std::to_string(a.numRegs) + " smem=" +\n             std::to_string(a.sharedSizeBytes + dyn) + " blocks/SM=" + std::to_string(blocks) + "; ";\n    }\n    return r;\n}\n'

_ext = load_inline(name="crisp_ds_probe", cpp_sources=[
    "#include <string>\nvoid ds_launch(int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t);\n"
    "std::string ds_info();\n"], cuda_sources=[_DS_CU], functions=["ds_launch", "ds_info"],
    extra_cuda_cflags=["-O3"], verbose=False)

_ARMS = {}
def _make(name, variant):
    ns = {"__name__": "arm_" + name}
    exec(compile(_ARM_SRC, "arm_" + name, "exec"), ns)
    if variant is not None:
        real = ns["_launch"]
        def _launch(k, groups, tensors, _real=real, _v=variant):
            if k != "sort_downsweep":
                return _real(k, groups, tensors)
            if ns["_lib"] is None:
                ns["_init"]()
            _ext.ds_launch(_v, tensors["src"][0], tensors["mm"][0], tensors["prm"][0], tensors["scanned"][0],
                           tensors["totals"][0], tensors["dst"][0], tensors["src"][1])
        ns["_launch"] = _launch
    _ARMS[name] = ns["custom_kernel"]

_make("crisp", None)
_make("cu_split2", 0)
_make("cu_ballot", 1)
_make("cu_match", 2)
_make("cu_ballot6", 3)

_done = False
def custom_kernel(data):
    global _done
    x, out = data
    if _done or x.numel() != 4096:
        return _ARMS["crisp"](data)
    _done = True
    from reference import generate_input
    from utils import clear_l2_cache
    lines = ["ds.cu: " + _ext.ds_info()]
    # correctness: every arm, several sizes and both distributions the task uses
    for n, seed, dist in ((1, 7123, "normal"), (4097, 4001, "uniform"), (1_000_003, 77, "normal"),
                          (1_000_003, 78, "duplicates"), (10_000_000, 8841, "normal"), (100_000_000, 6252, "normal")):
        try:
            x2, _ = generate_input(size=n, seed=seed, distribution=dist)
        except TypeError:
            x2, _ = generate_input(size=n, seed=seed)
        ref = torch.sort(x2)[0]
        oks = []
        for a, f in _ARMS.items():
            o = torch.empty_like(x2); f((x2, o)); torch.cuda.synchronize()
            oks.append(f"{a}={torch.equal(o, ref)}")
        lines.append(f"n={n} {dist}: " + " ".join(oks))
    # timing at the scored case: FIX input, clear_l2, events, mean of 8, interleaved
    base = generate_input(size=100_000_000, seed=6252)
    res = {a: [] for a in _ARMS}
    for rep in range(8):
        for a, f in _ARMS.items():
            o = torch.empty_like(base[0])
            torch.cuda.synchronize()
            e0 = torch.cuda.Event(enable_timing=True); e1 = torch.cuda.Event(enable_timing=True)
            clear_l2_cache()
            e0.record(); f((base[0], o)); e1.record()
            torch.cuda.synchronize()
            res[a].append(e0.elapsed_time(e1) * 1000.0)
    c = statistics.mean(res["crisp"])
    for a, g in res.items():
        m = statistics.mean(g)
        lines.append(f"{a:10s} mean={m:7.0f} median={statistics.median(g):7.0f} min={min(g):7.0f} us  "
                     f"vs crisp {m - c:+6.0f} us ({(m - c) / 3:+5.0f} per pass)  all={[round(v) for v in g]}")
    raise RuntimeError("DIAG-BALLOT\n" + "\n".join(lines))
